INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-front-squat', 'Front Squat', 'strength', 'quads,glutes,core', 'barbell', 'Elbows high, chest up. Bar rests on front delts, not wrists. Knees track over toes. Go to parallel or below. Keep torso upright — this is great for posture.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-landmine-press', 'Landmine Press', 'strength', 'shoulders,triceps,core', 'barbell', 'One hand on end of barbell in landmine. Stagger stance. Press up and slightly forward. Engages core heavily. Shoulder-friendly alternative to OHP for forward-head posture.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-ohp', 'Overhead Press', 'strength', 'shoulders,triceps', 'barbell', 'Bar starts at collarbone. Press straight up, head moves through at top. Brace core hard. If you feel it in front of shoulders more than back, switch to landmine press.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-incline-db-press', 'Incline DB Press', 'strength', 'chest,shoulders,triceps', 'dumbbell', 'Bench at 30-45 degrees. Retract shoulder blades, squeeze them together. Press up without letting shoulders roll forward. Better for posture than flat bench.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-bent-over-row', 'Bent Over Row', 'strength', 'back,biceps,rear_delts', 'barbell', 'Hinge at hips, back flat. Pull bar to lower chest. Squeeze shoulder blades at top. Keep elbows close. Fights the forward-shoulder posture from desk work.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-pullup-band', 'Pull-Up (Band Assisted)', 'strength', 'back,biceps,core', 'pull-up bar,band', 'Loop band over bar, place knee or foot in loop. Full dead hang at bottom, chin over bar at top. Focus on pulling with lats, not just arms. Build to unassisted.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-pullup-negative', 'Pull-Up (Negative)', 'strength', 'back,biceps,core', 'pull-up bar', 'Jump to top position (chin over bar). Lower yourself as slowly as possible — aim for 5 seconds down. Full extension at bottom. This builds the strength for real pull-ups.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-pullup', 'Pull-Up', 'strength', 'back,biceps,core', 'pull-up bar', 'Dead hang, shoulder-width grip. Pull until chin clears bar. Control the descent. Critical for MT clinch strength and countering desk posture.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-face-pulls', 'Face Pulls', 'strength', 'rear_delts,rotator_cuff,traps', 'cable,band', 'Cable or band at face height. Pull to face, externally rotate hands at end (pinkies back). Squeeze shoulder blades. Non-negotiable for posture — do every strength day.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-band-pull-aparts', 'Band Pull-Aparts', 'strength', 'rear_delts,rhomboids,traps', 'band', 'Hold band at arm''s length, shoulder width. Pull apart until band touches chest. Squeeze shoulder blades together. 15-20 reps. Warmup staple for posture correction.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-hanging-leg-raise', 'Hanging Leg Raise', 'core', 'lower_abs,hip_flexors', 'pull-up bar', 'Dead hang. Raise legs to parallel or higher without swinging. Control the descent. If too hard, bend knees (hanging knee raise).', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-ab-wheel', 'Ab Wheel Roll-Out', 'core', 'abs,lats,shoulders', 'ab wheel', 'Kneel on pad. Roll out as far as you can control, then pull back. Keep lower back from sagging. Start with partial range if needed.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-v-ups', 'V-Ups', 'core', 'abs', 'bodyweight', 'Lie flat. Simultaneously raise legs and torso to touch toes at the top. Control down. Keep legs as straight as possible.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-russian-twists', 'Russian Twists', 'core', 'obliques,abs', 'bodyweight', 'Sit, lean back 45 degrees, feet off ground. Rotate side to side, touching floor each side. Add weight when ready. Important for rotational power in MT.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-side-plank-lift', 'Side Plank + Lift', 'core', 'obliques,glutes', 'bodyweight', 'Side plank on elbow. Lift top leg. Hold 30s each side. Builds anti-rotation stability for strikes and clinch.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-doorway-pec-stretch', 'Doorway Pec Stretch', 'posture', 'chest,front_delts', 'doorway', 'Forearm on doorframe at 90 degrees. Step through gently. Hold 30-45s each side. Opens the chest that gets tight from desk posture. Do daily.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-foam-roller-thoracic', 'Foam Roller Thoracic Extensions', 'posture', 'thoracic_spine,upper_back', 'foam roller', 'Lie on foam roller at mid-back. Hands behind head. Extend backward over roller. Move roller up/down spine. Opens thoracic spine to fight rounded upper back.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-cat-cow', 'Cat-Cow', 'posture', 'spine,core', 'bodyweight', 'On all fours. Arch back up (cat), then drop belly and look up (cow). Move slowly with breath. Warms up entire spine and teaches segmental movement.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-chin-tucks', 'Chin Tucks', 'posture', 'deep_neck_flexors', 'bodyweight', 'Sitting or standing tall. Pull chin straight back (make a double chin). Hold 5-10s. Strengthens deep neck flexors that are weak from forward head posture. Do 10-15 reps.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-wall-slides', 'Wall Slides', 'posture', 'serratus,lower_traps,rotator_cuff', 'wall', 'Back flat against wall. Arms up in goalpost position, back of hands on wall. Slide arms up and down keeping contact with wall. If you can''t keep contact, that shows how tight you are.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-prone-y-raises', 'Prone Y Raises', 'posture', 'lower_traps,rear_delts', 'bodyweight', 'Lie face down. Arms form a Y shape. Lift arms off ground, squeeze shoulder blades down and together. Hold 2-3s at top. Activates the muscles that pull shoulders back.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-cossack-squats', 'Cossack Squats', 'mobility', 'adductors,hips,ankles', 'bodyweight', 'Wide stance. Shift weight to one side, sinking deep. Other leg stays straight. Alternate sides. Deep hip stretch + stability. Great for MT kick flexibility.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-90-90-hip-switches', '90/90 Hip Switches', 'mobility', 'hips,glutes', 'bodyweight', 'Sit on floor, both legs at 90 degrees. Rotate knees to switch sides without using hands. Smooth rotation, control the movement. Opens hip internal and external rotation.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-pigeon-stretch', 'Pigeon Stretch', 'mobility', 'glutes,hip_flexors', 'bodyweight', 'Front leg bent 90 degrees in front. Back leg extended. Sink hips down and forward. Hold 45s each side. Deep glute and external rotation stretch.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-wall-hip-cars', 'Wall Hip CARs', 'mobility', 'hips', 'wall', 'Face wall, hands on wall for balance. Lift knee high, rotate outward in largest circle possible, then reverse. Controlled articular rotation — builds usable hip range.', 1775929217);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, created_at) VALUES ('ex-wall-angels', 'Wall Angels', 'mobility', 'thoracic_spine,shoulders', 'wall', 'Back against wall, arms in goalpost. Slide arms up overhead keeping back and arms on wall. If your lower back arches off, brace core harder. Thoracic mobility + shoulder health.', 1775929217);
